static Lobe evalMaterial(const Hit& h, vec3f wo, f32 u) {
#if CDL_MONO
  return sec_evalMaterial(h, wo, u);
#else
  return gSec->evalMaterial(h, wo, u);
#endif
}
static f32 sdUser(i32 k, vec3f p) {
#if CDL_MONO
  return sec_sdUser(k, p);
#else
  return gSec->sdUser(k, p);
#endif
}
static f32 heightAt(i32 k, vec2f xz) {
#if CDL_MONO
  return sec_heightAt(k, xz);
#else
  return gSec->heightAt(k, xz);
#endif
}
static f32 densityOf(i32 m, vec3f P) {
#if CDL_MONO
  return sec_densityOf(m, P);
#else
  return gSec->densityOf(m, P);
#endif
}
static vec3f customKernel(vec3f ro, vec3f rd) {
#if CDL_MONO
  return sec_customKernel(ro, rd);
#else
  return gSec->customKernel(ro, rd);
#endif
}
